import React from 'react';
import {
  Alert,
  Box,
  Button,
  Checkbox,
  Chip,
  FormControlLabel,
  Grid,
  IconButton,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import AddCircleOutline from '@mui/icons-material/AddCircleOutline';
import DeleteOutline from '@mui/icons-material/DeleteOutline';

export type LegalEntityRow = {
  name: string;
  relationshipType: string;
  consolidationBasis: string;
};

export type RelatedPartyRow = {
  name: string;
  ownershipPercent: string;
  operationalControl: boolean;
  country?: string;
};

export type HoldingCompanyDraft = {
  name: string;
  ownershipPercent: string;
  country: string;
  includedInBoundary: boolean;
};

export type OrgBoundaryDraft = {
  consolidationApproach: string;
  reportingEntityDescription: string;
  includedLegalEntities: LegalEntityRow[];
  jointVentureEmissionAllocation: string;
  franchisesOrOutsourcedOperationsTreatment: string;
  nonControlledOperationsExcluded: boolean;
  organizationalBoundaryNotes: string;
  onSiteFuelCombustion?: string;
  fleetControl?: string;
  logisticsArrangement?: string;
  reportingEquitySharePercent?: string;
  singleLegalEntity?: boolean;
  holdingCompany?: HoldingCompanyDraft;
  subsidiaries?: RelatedPartyRow[];
  jointVentures?: RelatedPartyRow[];
};

type OrganizationalBoundaryEaseProps = {
  value: OrgBoundaryDraft;
  onChange: (next: OrgBoundaryDraft) => void;
  disabled?: boolean;
};

const APPROACHES = [
  {
    value: 'operational_control',
    title: 'We run the plants',
    hint: 'Recommended. Count every site your team operates, even if you do not own all of it.',
    basis: 'operational control',
  },
  {
    value: 'financial_control',
    title: 'We own the finances',
    hint: 'Count sites you steer through budgets and financial policy.',
    basis: 'financial control',
  },
  {
    value: 'equity_share',
    title: 'We count our ownership %',
    hint: 'Count only your share of each joint venture or subsidiary.',
    basis: 'equity share',
  },
] as const;

const SITE_PRESETS = [
  { relationshipType: 'plant', label: 'Our plant' },
  { relationshipType: 'branch', label: 'Branch' },
  { relationshipType: 'subsidiary', label: 'Subsidiary' },
  { relationshipType: 'warehouse', label: 'Warehouse' },
] as const;

const JV_CHOICES = [
  { value: 'not_applicable', label: 'No joint ventures' },
  { value: 'operational_share', label: 'Split by who operates' },
  { value: 'proportional_equity', label: 'Split by ownership %' },
] as const;

function basisFor(approach: string): string {
  return APPROACHES.find((item) => item.value === approach)?.basis || 'operational control';
}

const emptyHolding = (): HoldingCompanyDraft => ({
  name: '',
  ownershipPercent: '',
  country: 'India',
  includedInBoundary: false,
});

export function organizationalBoundaryIssues(value: OrgBoundaryDraft): string[] {
  const issues: string[] = [];
  if (!value.consolidationApproach) {
    issues.push('Select a consolidation approach (operational control, financial control, or equity share).');
  }
  if (value.reportingEntityDescription.trim().length < 12) {
    issues.push('Describe the reporting entity (at least a company name and the sites in the inventory).');
  }
  if (!value.jointVentureEmissionAllocation) {
    issues.push('Choose how joint-venture emissions are allocated.');
  }
  if (!value.franchisesOrOutsourcedOperationsTreatment.trim()) {
    issues.push('State how franchises or outsourced operations are treated. Enter None if there are none.');
  }
  const holding = value.holdingCompany || emptyHolding();
  const subsidiaries = value.subsidiaries || [];
  const jointVentures = value.jointVentures || [];
  const namedRelated = [
    holding.name.trim() ? holding : null,
    ...subsidiaries.filter((row) => row.name.trim()),
    ...jointVentures.filter((row) => row.name.trim()),
  ].filter(Boolean);
  if (!value.singleLegalEntity && namedRelated.length === 0 && value.includedLegalEntities.every((row) => !row.name.trim())) {
    issues.push('Confirm this is a single legal entity, or add the holding company, a subsidiary, or a joint venture.');
  }
  if (!value.onSiteFuelCombustion || value.onSiteFuelCombustion === 'unknown') {
    issues.push('Say whether this company burns fuel in equipment it operates. That decides Scope 1 versus contractor Scope 3.');
  }
  if (!value.fleetControl || value.fleetControl === 'unknown') {
    issues.push('Say whether the company operates its own vehicles.');
  }
  if (!value.logisticsArrangement || value.logisticsArrangement === 'unknown') {
    issues.push('Say whether goods move on company vehicles, contractor vehicles, or both.');
  }
  if (value.consolidationApproach === 'equity_share') {
    const share = Number(value.reportingEquitySharePercent);
    if (!Number.isFinite(share) || share <= 0 || share > 100) {
      issues.push('Equity share needs the percent of emissions this company counts (1 to 100).');
    }
  }
  if (value.consolidationApproach === 'equity_share') {
    namedRelated.forEach((row) => {
      const pct = Number((row as RelatedPartyRow | HoldingCompanyDraft).ownershipPercent);
      if (!Number.isFinite(pct) || pct <= 0 || pct > 100) {
        issues.push(`Equity share requires an ownership percent for ${((row as HoldingCompanyDraft).name || 'each related party')}.`);
      }
    });
  }
  return issues;
}

const OrganizationalBoundaryEase: React.FC<OrganizationalBoundaryEaseProps> = ({
  value,
  onChange,
  disabled = false,
}) => {
  const selected = APPROACHES.find((item) => item.value === value.consolidationApproach) || APPROACHES[0];
  const holding = value.holdingCompany || emptyHolding();
  const subsidiaries = value.subsidiaries || [];
  const jointVentures = value.jointVentures || [];
  const issues = organizationalBoundaryIssues(value);

  const addSite = (relationshipType: string, label: string) => {
    onChange({
      ...value,
      includedLegalEntities: [
        ...value.includedLegalEntities,
        { name: label, relationshipType, consolidationBasis: basisFor(value.consolidationApproach) },
      ],
    });
  };

  return (
    <Stack spacing={2} data-testid="org-boundary-ease">
      <Box
        component="figure"
        sx={{
          m: 0,
          p: { xs: 1.5, md: 2 },
          border: '2px dashed',
          borderColor: '#0f766e',
          borderRadius: 2,
          bgcolor: (theme) => alpha('#ecfdf5', theme.palette.mode === 'dark' ? 0.08 : 0.65),
        }}
        aria-label="Which operations sit inside your company boundary"
      >
        <Typography component="figcaption" variant="subtitle2" sx={{ fontWeight: 800, color: '#0f766e' }}>
          Inside your company
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
          {selected.hint} Suppliers and contractors stay outside unless you add them.
        </Typography>
        <Grid container spacing={1.5}>
          {APPROACHES.map((approach) => {
            const active = value.consolidationApproach === approach.value;
            return (
              <Grid item xs={12} md={4} key={approach.value}>
                <Box
                  component="button"
                  type="button"
                  disabled={disabled}
                  data-testid={`org-approach-${approach.value}`}
                  aria-pressed={active}
                  onClick={() => onChange({
                    ...value,
                    consolidationApproach: approach.value,
                    includedLegalEntities: value.includedLegalEntities.map((row) => ({
                      ...row,
                      consolidationBasis: approach.basis,
                    })),
                  })}
                  sx={{
                    width: '100%',
                    height: '100%',
                    textAlign: 'left',
                    cursor: disabled ? 'default' : 'pointer',
                    borderRadius: 2,
                    p: 1.5,
                    border: '2px solid',
                    borderColor: active ? '#0f766e' : 'divider',
                    bgcolor: active ? alpha('#0f766e', 0.1) : 'background.paper',
                    color: 'text.primary',
                  }}
                >
                  <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 0.5 }}>
                    <Typography variant="subtitle2" sx={{ fontWeight: 800 }}>
                      {approach.title}
                    </Typography>
                    {approach.value === 'operational_control' ? (
                      <Chip size="small" label="Usual" color="success" sx={{ height: 20, fontWeight: 700 }} />
                    ) : null}
                  </Stack>
                  <Typography variant="caption" color="text.secondary" sx={{ display: 'block', lineHeight: 1.4 }}>
                    {approach.hint}
                  </Typography>
                </Box>
              </Grid>
            );
          })}
        </Grid>
      </Box>

      <Box>
        <Typography variant="subtitle2" sx={{ fontWeight: 800, mb: 0.5 }}>
          Sites we count
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
          Tap a site type. Rename it if you have more than one.
        </Typography>
        <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mb: 1.5 }}>
          {SITE_PRESETS.map((preset) => (
            <Chip
              key={preset.relationshipType}
              icon={<AddCircleOutline />}
              label={preset.label}
              onClick={() => addSite(preset.relationshipType, preset.label)}
              disabled={disabled}
              variant="outlined"
              data-testid={`org-site-preset-${preset.relationshipType}`}
            />
          ))}
        </Stack>
        <Stack spacing={1}>
          {value.includedLegalEntities.length === 0 ? (
            <Typography variant="body2" color="text.secondary">
              No extra sites yet. Your main company is already inside the boundary.
            </Typography>
          ) : null}
          {value.includedLegalEntities.map((row, index) => (
            <Grid container spacing={1} key={`legal-entity-${index}`} alignItems="center">
              <Grid item xs={12} md={5}>
                <TextField
                  fullWidth
                  size="small"
                  label="Site name"
                  value={row.name}
                  disabled={disabled}
                  onChange={(event) => {
                    const next = [...value.includedLegalEntities];
                    next[index] = { ...next[index], name: event.target.value };
                    onChange({ ...value, includedLegalEntities: next });
                  }}
                />
              </Grid>
              <Grid item xs={8} md={6}>
                <Typography variant="body2" color="text.secondary">
                  {row.relationshipType || 'site'} · {row.consolidationBasis || selected.basis}
                </Typography>
              </Grid>
              <Grid item xs={4} md={1}>
                <IconButton
                  aria-label="Remove site"
                  disabled={disabled}
                  onClick={() => onChange({
                    ...value,
                    includedLegalEntities: value.includedLegalEntities.filter((_, i) => i !== index),
                  })}
                >
                  <DeleteOutline />
                </IconButton>
              </Grid>
            </Grid>
          ))}
        </Stack>
      </Box>

      <TextField
        fullWidth
        size="small"
        label="This inventory is for"
        value={value.reportingEntityDescription}
        disabled={disabled}
        onChange={(event) => onChange({ ...value, reportingEntityDescription: event.target.value })}
        placeholder="e.g. Acme Metals — Pune plant and Nashik warehouse"
      />

      <Box>
        <Typography variant="subtitle2" sx={{ fontWeight: 800 }}>
          Organizational boundary — holding company, subsidiaries, joint ventures
        </Typography>
        <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mb: 1 }}>
          GHG Protocol Corporate Standard consolidation. Required before the inventory is used in calculations.
        </Typography>
        <FormControlLabel
          control={(
            <Checkbox
              checked={Boolean(value.singleLegalEntity)}
              disabled={disabled}
              onChange={(event) => onChange({ ...value, singleLegalEntity: event.target.checked })}
            />
          )}
          label="Single legal entity — no holding company, subsidiaries, or joint ventures"
        />
        <Grid container spacing={1} sx={{ mt: 0.5 }}>
          <Grid item xs={12} md={5}>
            <TextField
              fullWidth
              size="small"
              label="Holding company"
              value={holding.name}
              disabled={disabled}
              onChange={(event) => onChange({
                ...value,
                holdingCompany: { ...holding, name: event.target.value },
              })}
            />
          </Grid>
          <Grid item xs={6} md={3}>
            <TextField
              fullWidth
              size="small"
              label="Ownership %"
              value={holding.ownershipPercent}
              disabled={disabled}
              onChange={(event) => onChange({
                ...value,
                holdingCompany: { ...holding, ownershipPercent: event.target.value },
              })}
            />
          </Grid>
          <Grid item xs={6} md={4}>
            <TextField
              fullWidth
              size="small"
              label="Country"
              value={holding.country}
              disabled={disabled}
              onChange={(event) => onChange({
                ...value,
                holdingCompany: { ...holding, country: event.target.value },
              })}
            />
          </Grid>
        </Grid>
        <Typography variant="body2" sx={{ mt: 1.5, fontWeight: 700 }}>Subsidiaries</Typography>
        {subsidiaries.map((row, index) => (
          <Grid container spacing={1} key={`subsidiary-${index}`} sx={{ mt: 0.5 }} alignItems="center">
            <Grid item xs={12} md={5}>
              <TextField
                fullWidth
                size="small"
                label="Subsidiary name"
                value={row.name}
                disabled={disabled}
                onChange={(event) => {
                  const next = [...subsidiaries];
                  next[index] = { ...next[index], name: event.target.value };
                  onChange({ ...value, subsidiaries: next });
                }}
              />
            </Grid>
            <Grid item xs={8} md={3}>
              <TextField
                fullWidth
                size="small"
                label="Ownership %"
                value={row.ownershipPercent}
                disabled={disabled}
                onChange={(event) => {
                  const next = [...subsidiaries];
                  next[index] = { ...next[index], ownershipPercent: event.target.value };
                  onChange({ ...value, subsidiaries: next });
                }}
              />
            </Grid>
            <Grid item xs={4} md={1}>
              <IconButton
                aria-label="Remove subsidiary"
                disabled={disabled}
                onClick={() => onChange({
                  ...value,
                  subsidiaries: subsidiaries.filter((_, i) => i !== index),
                })}
              >
                <DeleteOutline />
              </IconButton>
            </Grid>
          </Grid>
        ))}
        <Button
          size="small"
          startIcon={<AddCircleOutline />}
          disabled={disabled}
          onClick={() => onChange({
            ...value,
            subsidiaries: [...subsidiaries, { name: '', ownershipPercent: '100', operationalControl: true }],
          })}
        >
          Add subsidiary
        </Button>
        <Typography variant="body2" sx={{ mt: 1.5, fontWeight: 700 }}>
          Joint ventures — equity share or operational control
        </Typography>
        <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ my: 1 }}>
          {JV_CHOICES.map((choice) => (
            <Chip
              key={choice.value}
              label={choice.label}
              color={value.jointVentureEmissionAllocation === choice.value ? 'primary' : 'default'}
              variant={value.jointVentureEmissionAllocation === choice.value ? 'filled' : 'outlined'}
              onClick={() => onChange({ ...value, jointVentureEmissionAllocation: choice.value })}
              disabled={disabled}
            />
          ))}
        </Stack>
        {jointVentures.map((row, index) => (
          <Grid container spacing={1} key={`jv-${index}`} sx={{ mt: 0.5 }}>
            <Grid item xs={12} md={5}>
              <TextField
                fullWidth
                size="small"
                label="Joint venture"
                value={row.name}
                disabled={disabled}
                onChange={(event) => {
                  const next = [...jointVentures];
                  next[index] = { ...next[index], name: event.target.value };
                  onChange({ ...value, jointVentures: next });
                }}
              />
            </Grid>
            <Grid item xs={8} md={3}>
              <TextField
                fullWidth
                size="small"
                label="Ownership %"
                value={row.ownershipPercent}
                disabled={disabled}
                onChange={(event) => {
                  const next = [...jointVentures];
                  next[index] = { ...next[index], ownershipPercent: event.target.value };
                  onChange({ ...value, jointVentures: next });
                }}
              />
            </Grid>
            <Grid item xs={4} md={1}>
              <IconButton
                aria-label="Remove joint venture"
                disabled={disabled}
                onClick={() => onChange({
                  ...value,
                  jointVentures: jointVentures.filter((_, i) => i !== index),
                })}
              >
                <DeleteOutline />
              </IconButton>
            </Grid>
          </Grid>
        ))}
        <Button
          size="small"
          startIcon={<AddCircleOutline />}
          disabled={disabled}
          onClick={() => onChange({
            ...value,
            jointVentures: [...jointVentures, { name: '', ownershipPercent: '', operationalControl: false }],
          })}
        >
          Add joint venture
        </Button>
      </Box>

      <TextField
        fullWidth
        required
        size="small"
        multiline
        minRows={2}
        label="Franchises and outsourced operations"
        value={value.franchisesOrOutsourcedOperationsTreatment}
        disabled={disabled}
        onChange={(event) => onChange({
          ...value,
          franchisesOrOutsourcedOperationsTreatment: event.target.value,
        })}
        placeholder="None, or name the outlets inside the operational boundary"
        helperText="Required. GHG Protocol treatment of franchises and outsourced operations."
      />
      <FormControlLabel
        control={(
          <Checkbox
            checked={value.nonControlledOperationsExcluded}
            disabled={disabled}
            onChange={(event) => onChange({
              ...value,
              nonControlledOperationsExcluded: event.target.checked,
            })}
          />
        )}
        label="Exclude operations without operational or financial control"
      />
      <Box data-testid="org-scope-segregation">
        <Typography variant="subtitle2" sx={{ fontWeight: 800, mb: 0.5 }}>
          What the company operates
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
          These answers split fuel and freight bills into Scope 1 (you operate the equipment) or Scope 3 (a contractor does).
        </Typography>
        <Typography variant="caption" sx={{ fontWeight: 700 }}>Fuel burned in equipment you operate</Typography>
        <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mb: 1, mt: 0.5 }}>
          {[
            ['yes', 'Yes, on our sites'],
            ['no', 'No, we do not burn fuel'],
          ].map(([choice, label]) => (
            <Chip
              key={choice}
              label={label}
              color={value.onSiteFuelCombustion === choice ? 'primary' : 'default'}
              variant={value.onSiteFuelCombustion === choice ? 'filled' : 'outlined'}
              disabled={disabled}
              data-testid={`org-fuel-${choice}`}
              onClick={() => onChange({ ...value, onSiteFuelCombustion: choice })}
            />
          ))}
        </Stack>
        <Typography variant="caption" sx={{ fontWeight: 700 }}>Vehicles the company operates</Typography>
        <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mb: 1, mt: 0.5 }}>
          {[
            ['owned_or_leased', 'We operate vehicles'],
            ['no_fleet', 'No company vehicles'],
            ['mixed', 'Some of each'],
          ].map(([choice, label]) => (
            <Chip
              key={choice}
              label={label}
              color={value.fleetControl === choice ? 'primary' : 'default'}
              variant={value.fleetControl === choice ? 'filled' : 'outlined'}
              disabled={disabled}
              data-testid={`org-fleet-${choice}`}
              onClick={() => onChange({ ...value, fleetControl: choice })}
            />
          ))}
        </Stack>
        <Typography variant="caption" sx={{ fontWeight: 700 }}>Who moves goods</Typography>
        <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mt: 0.5 }}>
          {[
            ['company_operated', 'Our vehicles'],
            ['contracted', 'Contractors'],
            ['both', 'Both'],
          ].map(([choice, label]) => (
            <Chip
              key={choice}
              label={label}
              color={value.logisticsArrangement === choice ? 'primary' : 'default'}
              variant={value.logisticsArrangement === choice ? 'filled' : 'outlined'}
              disabled={disabled}
              data-testid={`org-logistics-${choice}`}
              onClick={() => onChange({ ...value, logisticsArrangement: choice })}
            />
          ))}
        </Stack>
      </Box>
      {value.consolidationApproach === 'equity_share' ? (
        <TextField
          fullWidth
          required
          size="small"
          type="number"
          label="Equity share counted in this inventory (%)"
          value={value.reportingEquitySharePercent || ''}
          disabled={disabled}
          onChange={(event) => onChange({ ...value, reportingEquitySharePercent: event.target.value })}
          helperText="GHG Protocol equity share. 40 counts 40% of each activity."
          inputProps={{ min: 1, max: 100, 'data-testid': 'org-equity-percent' }}
        />
      ) : null}
      <TextField
        fullWidth
        size="small"
        multiline
        minRows={2}
        label="Organizational boundary notes"
        value={value.organizationalBoundaryNotes}
        disabled={disabled}
        onChange={(event) => onChange({ ...value, organizationalBoundaryNotes: event.target.value })}
      />
      {issues.length > 0 ? (
        <Alert severity="warning">
          {issues[0]}
        </Alert>
      ) : (
        <Alert severity="success">Organizational boundary is complete for inventory calculations.</Alert>
      )}

      <Button
        variant="text"
        size="small"
        startIcon={<AddCircleOutline />}
        disabled={disabled}
        onClick={() => addSite('other', '')}
        sx={{ alignSelf: 'flex-start' }}
      >
        Add another site
      </Button>
    </Stack>
  );
};

export default OrganizationalBoundaryEase;
