import React, { useCallback, useEffect, useRef, useState } from 'react';
import {
  Alert,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  Link,
  Stack,
  Typography,
} from '@mui/material';
import { CameraAlt as CameraIcon, GpsFixed as GpsIcon } from '@mui/icons-material';
import documentService from '../../services/documentService';
import ApiService from '../../services/api';
import {
  GeotaggedEvidenceWorkflow,
  getGeotaggedWorkflowConfig,
} from '../../constants/geotaggedEvidenceWorkflows';
import { embedGpsCoordinatesInImage } from '../../utils/gpsImageEmbed';
import {
  buildMapsLink,
  formatGpsLabel,
  getCurrentGpsCoordinates,
  GpsCoordinates,
  isImageFile,
} from '../../utils/geolocation';

type GpsGeotaggedCaptureProps = {
  workflow: GeotaggedEvidenceWorkflow;
  period?: string;
  statusChip?: { label: string; color?: 'success' | 'warning' | 'default' };
  statusDetail?: string | null;
  onComplete?: () => void;
  /** When false, do not auto-prompt the browser for location on mount (profile optional capture). */
  autoRequestGps?: boolean;
  /** Softer copy + non-blocking GPS prompts for optional registration/profile use. */
  optional?: boolean;
};

const GpsGeotaggedCapture: React.FC<GpsGeotaggedCaptureProps> = ({
  workflow,
  period = 'annual',
  statusChip,
  statusDetail,
  onComplete,
  autoRequestGps = true,
  optional = false,
}) => {
  const config = getGeotaggedWorkflowConfig(workflow);
  const fileInputRef = useRef<HTMLInputElement | null>(null);
  const [gps, setGps] = useState<GpsCoordinates | null>(null);
  const [gpsLoading, setGpsLoading] = useState(Boolean(autoRequestGps));
  const [gpsError, setGpsError] = useState<string | null>(null);
  const [processing, setProcessing] = useState(false);
  const [success, setSuccess] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const refreshGps = useCallback(async () => {
    setGpsLoading(true);
    setGpsError(null);
    const result = await getCurrentGpsCoordinates({ enableHighAccuracy: true, timeoutMs: 20000 });
    setGpsLoading(false);
    if (!result.ok) {
      setGps(null);
      setGpsError(
        optional
          ? 'Location not available right now. You can still upload a site photo without GPS, or retry later.'
          : result.error
      );
      return null;
    }
    setGps(result.coords);
    return result.coords;
  }, [optional]);

  useEffect(() => {
    if (!autoRequestGps) {
      setGpsLoading(false);
      return;
    }
    void refreshGps();
  }, [autoRequestGps, refreshGps]);

  const mapsLink = buildMapsLink(gps);

  const processAndUpload = async (file: File) => {
    setProcessing(true);
    setError(null);
    setSuccess(null);

    try {
      let coords = gps;
      if (!coords && !gpsError) {
        coords = await refreshGps();
      }
      // GPS preferred but not required — allow photo upload when permission is denied.

      if (!isImageFile(file)) {
        throw new Error('Please capture a photo (JPG or PNG).');
      }

      const validation = documentService.validateFile(file);
      if (!validation.valid) {
        throw new Error(validation.error || 'Invalid image file.');
      }

      let uploadFile = file;
      let gpsEmbeddedInImage = false;
      if (coords) {
        uploadFile = await embedGpsCoordinatesInImage(file, {
          coords,
          purposeLabel: config.purposeLabel,
        });
        gpsEmbeddedInImage = uploadFile !== file;
      }

      const notes = coords
        ? `${config.notesTemplate} · GPS ${coords.latitude.toFixed(6)}, ${coords.longitude.toFixed(6)}`
        : `${config.notesTemplate} · GPS not available (permission denied or unavailable)`;

      const uploadResult = await documentService.uploadDocument(
        uploadFile,
        'other',
        notes,
        'company',
        [],
        {
          sourceWorkflow: workflow,
          gpsLatitude: coords?.latitude,
          gpsLongitude: coords?.longitude,
          gpsAccuracyMeters: coords?.accuracyMeters,
          gpsCapturedAt: coords?.capturedAt,
          gpsEmbeddedInImage,
          gpsMissing: !coords,
        }
      );

      if (!uploadResult?.success) {
        throw new Error(uploadResult?.message || 'Upload failed');
      }

      const documentId = String(
        uploadResult.document?.id
        || (uploadResult.document as { _id?: string } | undefined)?._id
        || ''
      ).trim();

      let scoreDeltaMessage: string | undefined;
      if (documentId) {
        try {
          const orchestrationRes = await ApiService.orchestrateGeotaggedEvidence({
            documentId,
            sourceWorkflow: workflow,
            period,
            applyChanges: true,
            runAgents: true,
          });
          if ((orchestrationRes as { success?: boolean })?.success !== false) {
            const orchestrationData = (orchestrationRes as { data?: Record<string, unknown> })?.data
              || (orchestrationRes as Record<string, unknown>);
            const scoreDelta = orchestrationData?.scoreDelta as {
              message?: string;
            } | null | undefined;
            scoreDeltaMessage = scoreDelta?.message;
          }
        } catch {
          // Ignore — document is already stored; hub agents retry async.
        }
      }

      setSuccess(
        [
          coords
            ? `Geotagged photo uploaded with GPS (${formatGpsLabel(coords)})${gpsEmbeddedInImage ? ' stamped on image' : ' attached as metadata'}.`
            : 'Site photo uploaded without GPS. Re-enable location and re-capture later for stronger compliance evidence.',
          scoreDeltaMessage,
          `${config.reportingFrameworks.join(', ')} agents are processing evidence.`,
        ].filter(Boolean).join(' ')
      );
      onComplete?.();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to capture geotagged photo');
    } finally {
      setProcessing(false);
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
    }
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    void processAndUpload(file);
  };

  return (
    <Card variant="outlined">
      <CardContent>
        <Stack spacing={2}>
          <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap">
            <Typography variant="subtitle2">{config.label} — GPS photo capture</Typography>
            {statusChip ? (
              <Chip size="small" color={statusChip.color || 'default'} label={statusChip.label} />
            ) : null}
            {config.reportingFrameworks.map((framework) => (
              <Chip key={framework} size="small" variant="outlined" label={framework} />
            ))}
          </Stack>

          <Typography variant="body2" color="text.secondary">
            {optional
              ? 'Optional geotagged photo. Enable location only if you want GPS stamped on the image; otherwise upload a site photo without GPS.'
              : `${config.description}. When location is allowed, GPS is stamped on the image automatically. If permission is denied, you can still upload a site photo and retry GPS later.`}
          </Typography>

          {statusDetail ? (
            <Typography variant="body2" color="text.secondary">
              {statusDetail}
            </Typography>
          ) : null}

          {gpsLoading ? (
            <Alert severity="info" icon={<CircularProgress size={18} />}>
              Acquiring GPS signal… keep location enabled.
            </Alert>
          ) : gpsError ? (
            <Alert
              severity={optional ? 'info' : 'warning'}
              action={
                <Button color="inherit" size="small" onClick={() => void refreshGps()}>
                  Retry GPS
                </Button>
              }
            >
              {gpsError}
            </Alert>
          ) : gps ? (
            <Alert severity="success">
              Auto GPS ready: {formatGpsLabel(gps)}
              {gps.accuracyMeters ? ` (±${Math.round(gps.accuracyMeters)} m)` : ''}
              {mapsLink ? (
                <>
                  {' '}
                  ·{' '}
                  <Link href={mapsLink} target="_blank" rel="noopener noreferrer">
                    Preview on map
                  </Link>
                </>
              ) : null}
            </Alert>
          ) : null}

          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1}>
            <input
              ref={fileInputRef}
              type="file"
              accept="image/*"
              capture="environment"
              hidden
              onChange={handleFileChange}
            />
            <Button
              variant="contained"
              startIcon={processing ? <CircularProgress size={18} color="inherit" /> : <CameraIcon />}
              onClick={() => fileInputRef.current?.click()}
              disabled={processing || (!optional && gpsLoading)}
            >
              {processing
                ? (gps ? 'Embedding GPS & uploading…' : 'Uploading photo…')
                : (gps ? 'Capture geotagged photo' : 'Capture site photo')}
            </Button>
            <Button
              variant="outlined"
              startIcon={<GpsIcon />}
              onClick={() => void refreshGps()}
              disabled={processing || gpsLoading}
            >
              {optional && !gps && !gpsError ? 'Add GPS (optional)' : 'Refresh GPS'}
            </Button>
          </Stack>

          {error ? <Alert severity="error">{error}</Alert> : null}
          {success ? <Alert severity="success">{success}</Alert> : null}

          <Typography variant="caption" color="text.secondary">
            GPS-stamped photos strengthen {config.reportingFrameworks.join(', ')} evidence.
            Photos without GPS are still stored for review.
          </Typography>
        </Stack>
      </CardContent>
    </Card>
  );
};

export default GpsGeotaggedCapture;
